import { headers } from 'next/headers';

type UserPreferences = Record<string, unknown>;

function getPreferencesUrl() {
  const headersList = headers();
  const host =
    headersList.get('x-forwarded-host') ?? headersList.get('host');
  const protocol = headersList.get('x-forwarded-proto') ?? 'http';

  if (host) {
    return `${protocol}://${host}/api/user/preferences`;
  }

  return '/api/user/preferences';
}

async function getUserPreferences() {
  const res = await fetch(getPreferencesUrl(), {
    cache: 'no-store',
    headers: { Accept: 'application/json' }
  });

  if (!res.ok) {
    throw new Error(`Failed to load preferences (${res.status})`);
  }

  return (await res.json()) as UserPreferences;
}

function renderValue(value: unknown) {
  if (typeof value === 'boolean') {
    return value ? 'On' : 'Off';
  }

  if (value === null || value === undefined) {
    return 'Not set';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

export default async function UserDashboard() {
  let preferences: UserPreferences | null = null;
  let errorMessage: string | null = null;

  try {
    preferences = await getUserPreferences();
  } catch (error) {
    errorMessage =
      error instanceof Error ? error.message : 'Failed to load preferences.';
  }

  const entries = preferences ? Object.entries(preferences) : [];

  return (
    <section>
      <h2>User Dashboard</h2>
      <p>Current preferences (fresh each request)</p>
      {errorMessage ? (
        <p>{errorMessage}</p>
      ) : entries.length ? (
        <ul>
          {entries.map(([key, value]) => (
            <li key={key}>
              <strong>{key}:</strong> {renderValue(value)}
            </li>
          ))}
        </ul>
      ) : (
        <p>No preferences available yet.</p>
      )}
    </section>
  );
}
